# Rebuilds the Windows icons from the checked-in 256 px renders. The app icon
# uses outatime.png; the effect-free tray icon uses outatime-tray.png, and its
# paused variant is generated by converting that same artwork to grayscale.
# The MSIX package's images are made from outatime.png too.
Add-Type -AssemblyName System.Drawing

$sizes = 16, 20, 24, 30, 32, 36, 40, 48, 60, 64, 72, 80, 96, 256
$outDir = Join-Path (Split-Path $PSScriptRoot -Parent) 'src/Outatime/icons'
$assetsDir = Join-Path (Split-Path $PSScriptRoot -Parent) 'src/Outatime.Settings/Assets'
$appSourcePath = Join-Path $outDir 'outatime.png'
$traySourcePath = Join-Path $outDir 'outatime-tray.png'

# A $size px PNG with the artwork scaled to $artSize px in the middle.
function New-Frame(
    [System.Drawing.Image]$source,
    [int]$size,
    [bool]$monochrome,
    [int]$artSize = $size
) {
    $bitmap = New-Object System.Drawing.Bitmap $size, $size, ([System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
    $graphics = [System.Drawing.Graphics]::FromImage($bitmap)
    $graphics.CompositingQuality = 'HighQuality'
    $graphics.InterpolationMode = 'HighQualityBicubic'
    $graphics.PixelOffsetMode = 'HighQuality'
    $graphics.Clear([System.Drawing.Color]::Transparent)

    $offset = [int](($size - $artSize) / 2)
    $destination = New-Object System.Drawing.Rectangle $offset, $offset, $artSize, $artSize
    if ($monochrome) {
        # Rec. 709 luminance weights, with alpha preserved.
        $matrix = New-Object System.Drawing.Imaging.ColorMatrix
        $matrix.Matrix00 = 0.2126; $matrix.Matrix01 = 0.2126; $matrix.Matrix02 = 0.2126
        $matrix.Matrix10 = 0.7152; $matrix.Matrix11 = 0.7152; $matrix.Matrix12 = 0.7152
        $matrix.Matrix20 = 0.0722; $matrix.Matrix21 = 0.0722; $matrix.Matrix22 = 0.0722
        $attributes = New-Object System.Drawing.Imaging.ImageAttributes
        $attributes.SetColorMatrix($matrix)
        $graphics.DrawImage(
            $source,
            $destination,
            0,
            0,
            $source.Width,
            $source.Height,
            [System.Drawing.GraphicsUnit]::Pixel,
            $attributes
        )
        $attributes.Dispose()
    }
    else {
        $graphics.DrawImage($source, $destination)
    }

    $graphics.Dispose()
    $stream = New-Object System.IO.MemoryStream
    $bitmap.Save($stream, [System.Drawing.Imaging.ImageFormat]::Png)
    $bitmap.Dispose()
    return , $stream.ToArray()
}

function Write-Icon(
    [string]$path,
    [System.Drawing.Image]$source,
    [bool]$monochrome
) {
    $frames = foreach ($size in $sizes) { , (New-Frame $source $size $monochrome) }
    $out = New-Object System.IO.MemoryStream
    $writer = New-Object System.IO.BinaryWriter $out

    # ICONDIR
    $writer.Write([UInt16]0)
    $writer.Write([UInt16]1)
    $writer.Write([UInt16]$sizes.Count)

    $offset = 6 + 16 * $sizes.Count
    for ($i = 0; $i -lt $sizes.Count; $i++) {
        $size = $sizes[$i]
        # ICONDIRENTRY; a size of 256 is stored as 0.
        $writer.Write([byte]($size % 256))
        $writer.Write([byte]($size % 256))
        $writer.Write([byte]0)
        $writer.Write([byte]0)
        $writer.Write([UInt16]1)
        $writer.Write([UInt16]32)
        $writer.Write([UInt32]$frames[$i].Length)
        $writer.Write([UInt32]$offset)
        $offset += $frames[$i].Length
    }
    foreach ($frame in $frames) {
        $writer.Write($frame)
    }
    $writer.Flush()
    [System.IO.File]::WriteAllBytes($path, $out.ToArray())
    $writer.Dispose()
    $out.Dispose()
    Write-Host "Wrote $path"
}

function Write-Png([string]$name, [System.Drawing.Image]$source, [int]$size, [int]$artSize = $size) {
    $path = Join-Path $assetsDir $name
    [System.IO.File]::WriteAllBytes($path, (New-Frame $source $size $false $artSize))
    Write-Host "Wrote $path"
}

$appSource = [System.Drawing.Image]::FromFile($appSourcePath)
try {
    Write-Icon (Join-Path $outDir 'outatime.ico') $appSource $false

    # The 256 px source limits the scales. Windows picks the nearest one.
    Write-Png 'StoreLogo.scale-100.png' $appSource 50
    Write-Png 'StoreLogo.scale-200.png' $appSource 100
    # Medium tile, with the artwork at two thirds of the tile.
    Write-Png 'Square150x150Logo.scale-100.png' $appSource 150 100
    Write-Png 'Square150x150Logo.scale-150.png' $appSource 225 150
    Write-Png 'Square44x44Logo.scale-100.png' $appSource 44
    Write-Png 'Square44x44Logo.scale-200.png' $appSource 88
    # The taskbar and Start menu: plated for older Windows, unplated for Windows 11.
    foreach ($size in 16, 24, 32, 48, 256) {
        Write-Png "Square44x44Logo.targetsize-$size.png" $appSource $size
        Write-Png "Square44x44Logo.targetsize-${size}_altform-unplated.png" $appSource $size
    }
}
finally {
    $appSource.Dispose()
}

$traySource = [System.Drawing.Image]::FromFile($traySourcePath)
try {
    Write-Icon (Join-Path $outDir 'outatime-tray.ico') $traySource $false
    Write-Icon (Join-Path $outDir 'outatime-tray-paused.ico') $traySource $true
}
finally {
    $traySource.Dispose()
}
